use failures::*;

#[path = "concurrency.rs"]
mod concurrency;
use concurrency::*;

// First submission gets seq 1 regardless of durability policy.
#[test]
fn first_submission_is_seq_1_for_relaxed() -> Result<(), String> {
    fixtures::submit_first_is_seq_1(vb_core::RuntimePolicy::Relaxed)
}

#[test]
fn first_submission_is_seq_1_for_journaled() -> Result<(), String> {
    fixtures::submit_first_is_seq_1(vb_core::RuntimePolicy::Journaled)
}

